/**
 * Character classification helpers.
 *
 * Everything in this port is written as explicit character scanning, so these
 * predicates take the place of the character classes a pattern engine would
 * normally provide. They operate on single-character strings (or code points)
 * and never allocate.
 */

export const SPACE = ' ';
export const TAB = '\t';
export const NL = '\n';
export const CR = '\r';

/** Space or tab -- Python's notion of "blank" inside a line. */
export function isSpaceOrTab(ch) {
  return ch === ' ' || ch === '\t';
}

/**
 * Python `str.isspace()` for the characters that actually reach us:
 * space, tab, newline, carriage return, vertical tab, form feed.
 */
export function isWhitespace(ch) {
  return ch === ' ' || ch === '\t' || ch === '\n' || ch === '\r' || ch === '\v' || ch === '\f';
}

export function isDigit(ch) {
  return ch >= '0' && ch <= '9';
}

export function isAsciiLower(ch) {
  return ch >= 'a' && ch <= 'z';
}

export function isAsciiUpper(ch) {
  return ch >= 'A' && ch <= 'Z';
}

export function isAsciiAlpha(ch) {
  return isAsciiLower(ch) || isAsciiUpper(ch);
}

export function isAsciiAlnum(ch) {
  return isAsciiAlpha(ch) || isDigit(ch);
}

export function isHexDigit(ch) {
  return isDigit(ch) || (ch >= 'a' && ch <= 'f') || (ch >= 'A' && ch <= 'F');
}

/**
 * Characters legal in an HTML tag name as far as Python's `html.parser` is
 * concerned: it accepts letters, digits and a few punctuation marks.
 */
export function isTagNameChar(ch) {
  return isAsciiAlnum(ch) || ch === '-' || ch === '.' || ch === ':' || ch === '_';
}

export function isTagNameStart(ch) {
  return isAsciiAlpha(ch);
}

/** Characters legal at the start of an attribute name. */
export function isAttrNameChar(ch) {
  if (ch === undefined) return false;
  return !isWhitespace(ch) && ch !== '=' && ch !== '>' && ch !== '/' && ch !== '<' && ch !== '"' && ch !== "'";
}

/**
 * True when every character from `start` to `end` is a space or tab.
 * `end` defaults to the end of the string.
 */
export function isBlankRange(text, start = 0, end = -1) {
  const stop = end < 0 ? text.length : end;
  for (let i = start; i < stop; i++) {
    if (!isWhitespace(text[i])) return false;
  }
  return true;
}

/** True when the whole string is empty or only whitespace. */
export function isBlank(text) {
  return isBlankRange(text, 0, text.length);
}

/** Index of the first character that is not a space, or text.length. */
export function countLeadingSpaces(text) {
  let i = 0;
  while (i < text.length && text[i] === ' ') i++;
  return i;
}

/** Number of consecutive occurrences of `ch` starting at `start`. */
export function runLength(text, start, ch) {
  let i = start;
  while (i < text.length && text[i] === ch) i++;
  return i - start;
}

