/**
 * Python string semantics that JavaScript does not provide, or provides with
 * different edge-case behaviour.
 *
 * The conversion pipeline leans on these constantly, and they are the most
 * common source of off-by-one differences between the two languages, so each
 * one mirrors CPython exactly rather than approximating.
 */

import { isWhitespace } from './chars.mjs';

/**
 * `str.expandtabs(tabsize)`.
 *
 * Column-based, not a blind replace: a tab advances to the next multiple of
 * `tabsize`, and newlines and carriage returns reset the column counter.
 */
export function expandTabs(text, tabSize = 4) {
  let out = '';
  let col = 0;
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    if (ch === '\t') {
      if (tabSize > 0) {
        const width = tabSize - (col % tabSize);
        out += ' '.repeat(width);
        col += width;
      }
    } else {
      out += ch;
      if (ch === '\n' || ch === '\r') col = 0;
      else col += 1;
    }
  }
  return out;
}

/** `str.strip()` -- strips all Python whitespace from both ends. */
export function strip(text) {
  let start = 0;
  let end = text.length;
  while (start < end && isWhitespace(text[start])) start++;
  while (end > start && isWhitespace(text[end - 1])) end--;
  return text.slice(start, end);
}

/** `str.lstrip()`. */
export function lstrip(text) {
  let start = 0;
  while (start < text.length && isWhitespace(text[start])) start++;
  return text.slice(start);
}

/** `str.rstrip()`. */
export function rstrip(text) {
  let end = text.length;
  while (end > 0 && isWhitespace(text[end - 1])) end--;
  return text.slice(0, end);
}

/** `str.strip(chars)` -- strips any of the given characters from both ends. */
export function stripChars(text, chars) {
  let start = 0;
  let end = text.length;
  while (start < end && chars.includes(text[start])) start++;
  while (end > start && chars.includes(text[end - 1])) end--;
  return text.slice(start, end);
}

/** `str.lstrip(chars)`. */
export function lstripChars(text, chars) {
  let start = 0;
  while (start < text.length && chars.includes(text[start])) start++;
  return text.slice(start);
}

/** `str.rstrip(chars)`. */
export function rstripChars(text, chars) {
  let end = text.length;
  while (end > 0 && chars.includes(text[end - 1])) end--;
  return text.slice(0, end);
}

/**
 * Iterate the code points of a string.
 *
 * Python strings are sequences of code points; JavaScript strings are UTF-16
 * code units. Anything that counts or maps characters (slug generation, email
 * obfuscation) has to work in code points to match.
 */
export function codePoints(text) {
  return Array.from(text);
}

/** `'sep'.join(parts)` with the argument order Python uses. */
export function join(sep, parts) {
  return parts.join(sep);
}

/**
 * Replace every occurrence of `search` with `replacement`.
 *
 * `String.prototype.replaceAll` would do, but this keeps the pipeline free of
 * any dependence on pattern-matching semantics for special characters such as
 * `$&` in the replacement text.
 */
export function replaceAll(text, search, replacement) {
  if (search === '') return text;
  let out = '';
  let pos = 0;
  for (;;) {
    const idx = text.indexOf(search, pos);
    if (idx === -1) {
      out += text.slice(pos);
      return out;
    }
    out += text.slice(pos, idx) + replacement;
    pos = idx + search.length;
  }
}

/**
 * `str.startswith(prefix, start)`.
 */
export function startsWith(text, prefix, start = 0) {
  return text.startsWith(prefix, start);
}

/** `str.title()` restricted to the ASCII behaviour we need. */
export function isUpperCaseWord(text) {
  if (text.length === 0) return false;
  for (const ch of text) {
    if (ch >= 'a' && ch <= 'z') return false;
  }
  return true;
}

