/**
 * Sentinel strings and tuning constants shared across the pipeline.
 *
 * The two control characters bracket every placeholder the converter injects.
 * They are stripped from user input up front, so a document can never forge
 * one, and they are guaranteed not to collide with real content.
 */

/** Start of text -- opens a placeholder. */
export const STX = '';
/** End of text -- closes a placeholder. */
export const ETX = '';

/** Placeholder wrapper for a chunk of text pulled out of inline processing. */
export const INLINE_PLACEHOLDER_PREFIX = STX + 'klzzwxh:';

export function inlinePlaceholder(id) {
  return INLINE_PLACEHOLDER_PREFIX + id + ETX;
}

/** Placeholder wrapper for a stashed chunk of raw HTML. */
export const HTML_PLACEHOLDER_PREFIX = STX + 'wzxhzdk:';

export function htmlPlaceholder(id) {
  return HTML_PLACEHOLDER_PREFIX + id + ETX;
}

/**
 * Stand-in for a literal ampersand that must survive serialization without
 * being turned into `&amp;`. The final postprocessor swaps it back.
 */
export const AMP_SUBSTITUTE = STX + 'amp' + ETX;

/** Placeholder for a backslash-escaped character. */
export function escapePlaceholder(ch) {
  return STX + ch.codePointAt(0) + ETX;
}

export const TAB_LENGTH = 4;

/** Root element name; stripped off before the result is returned. */
export const DOC_TAG = 'div';

/** Block-level tags, as the reference implementation classifies them. */
export const BLOCK_LEVEL_ELEMENTS = new Set([
  'address', 'article', 'aside', 'blockquote', 'details', 'div', 'dl',
  'fieldset', 'figcaption', 'figure', 'footer', 'form', 'h1', 'h2', 'h3',
  'h4', 'h5', 'h6', 'header', 'hgroup', 'hr', 'main', 'menu', 'nav', 'ol',
  'p', 'pre', 'section', 'table', 'ul',
  // Not block level by the HTML spec, but treated as such here because they
  // may only appear inside one of the containers above.
  'dd', 'dt', 'li', 'tbody', 'td', 'tfoot', 'th', 'thead', 'tr',
  // Legacy and miscellaneous.
  'canvas', 'colgroup', 'dir', 'button', 'center', 'iframe', 'video',
  'audio', 'script', 'style', 'noscript', 'output', 'progress',
]);

export function isBlockLevel(tag) {
  if (typeof tag !== 'string' || tag.length === 0) return false;
  // Comments, processing instructions and declarations are handled elsewhere.
  if (tag[0] === '!' || tag[0] === '?') return false;
  return BLOCK_LEVEL_ELEMENTS.has(tag.toLowerCase());
}

/** Void elements -- serialized without a closing tag. */
export const HTML_EMPTY = new Set([
  'area', 'base', 'basefont', 'br', 'col', 'embed', 'frame', 'hr', 'img',
  'input', 'isindex', 'link', 'meta', 'param', 'source', 'track', 'wbr',
]);

