    this.tail = null;
  }

  set(key, value) {
    this.attrib.set(key, value);
    return this;
  }

  get(key, fallback = null) {
    return this.attrib.has(key) ? this.attrib.get(key) : fallback;
  }

  has(key) {
    return this.attrib.has(key);
  }

  delete(key) {
    this.attrib.delete(key);
  }

  /** Attribute pairs sorted by name, which is the order used on output. */
  sortedItems() {
    return [...this.attrib.entries()].sort((left, right) =>
      left[0] < right[0] ? -1 : left[0] > right[0] ? 1 : 0
    );
  }

  append(child) {
    this.children.push(child);
    return child;
  }

  insert(index, child) {
    this.children.splice(index, 0, child);
    return child;
  }

  remove(child) {
    const index = this.children.indexOf(child);
    if (index !== -1) this.children.splice(index, 1);
  }

  get length() {
    return this.children.length;
  }

  child(index) {
    return index < 0 ? this.children[this.children.length + index] : this.children[index];
  }

  indexOf(child) {
    return this.children.indexOf(child);
  }

  /** Depth-first iteration over this element and all descendants. */
  *iter(tag = null) {
    if (tag === null || tag === this.tag) yield this;
    for (const child of this.children) {
      yield* child.iter(tag);
    }
  }

  /** Every descendant element, excluding this one. */
  *descendants() {
    for (const child of this.children) {
      yield child;
      yield* child.descendants();
    }
  }
}

/** Create an element and append it to `parent` in one step. */
export function subElement(parent, tag, attrib = null) {
  return parent.append(new Element(tag, attrib));
}

/**
 * Map every element to its parent.
 *
 * The tree holds no upward links -- matching ElementTree -- so passes that
 * need to walk upward build this on demand.
 */
export function buildParentMap(root) {
  const parents = new Map();
  const walk = (element) => {
    for (const child of element.children) {
      parents.set(child, element);
      walk(child);
    }
  };
  walk(root);
  return parents;
}

