/**
 * Tree-to-HTML serialization.
 *
 * This is where byte-exactness is won or lost, so three behaviours are worth
 * calling out because they differ from what a general-purpose HTML serializer
 * would do:
 *
 *  1. Attributes are emitted in sorted-by-name order, not insertion order.
 *     `<img alt="..." src="..." />` rather than `<img src="..." alt="..." />`.
 *  2. An ampersand is only escaped when it does not already begin something
 *     that *looks* like a character reference. The test is purely syntactic --
 *     `&notanentity;` is left alone even though no such entity exists --
 *     because it matches on shape, not on a table lookup.
 *  3. Void elements close as ` />`, and an element with no children and no
 *     text still gets a full open/close pair unless it is void.
 */

import { HTML_EMPTY } from './constants.mjs';
import { textOf } from './element.mjs';
import { isAsciiAlnum, isDigit, isHexDigit } from '../util/chars.mjs';

/**
 * Would `&` at `index` start something shaped like a character reference?
 *
 * Accepts `&#<digits>;`, `&#x<hex>;` and `&<alphanumerics>;`. Case-insensitive
 * for the `x` and the hex digits.
 */
function looksLikeCharRef(text, index) {
  let i = index + 1;
  if (i >= text.length) return false;

  if (text[i] === '#') {
    i += 1;
    if (i < text.length && (text[i] === 'x' || text[i] === 'X')) {
      i += 1;
      const start = i;
      while (i < text.length && isHexDigit(text[i])) i++;
      if (i === start) return false;
      return text[i] === ';';
    }
    const start = i;
    while (i < text.length && isDigit(text[i])) i++;
    if (i === start) return false;
    return text[i] === ';';
  }

  const start = i;
  while (i < text.length && isAsciiAlnum(text[i])) i++;
  if (i === start) return false;
  return text[i] === ';';
}

/** Escape `&` where it is not already part of a reference-shaped sequence. */
function escapeAmpersands(text) {
  if (!text.includes('&')) return text;
  let out = '';
  for (let i = 0; i < text.length; i++) {
    if (text[i] === '&' && !looksLikeCharRef(text, i)) out += '&amp;';
    else out += text[i];
  }
  return out;
}

/** Escape character data: `&`, `<`, `>`. Quotes are left as-is. */
export function escapeCdata(text) {
  let out = escapeAmpersands(text);
  if (out.includes('<')) out = out.split('<').join('&lt;');
  if (out.includes('>')) out = out.split('>').join('&gt;');
  return out;
}

/** Escape an attribute value: character data plus `"` and newlines. */
export function escapeAttrib(text) {
  let out = escapeAmpersands(String(text));
  if (out.includes('<')) out = out.split('<').join('&lt;');
  if (out.includes('>')) out = out.split('>').join('&gt;');
  if (out.includes('"')) out = out.split('"').join('&quot;');
  if (out.includes('\n')) out = out.split('\n').join('&#10;');
  return out;
}

/**
 * Serialize one node and its subtree, appending to `parts`.
 *
 * Comments, processing instructions and declarations are represented by a tag
 * that is a function in ElementTree; here they carry a sentinel tag name and
 * are written through without escaping.
 */
function serializeElement(parts, element) {
  const tag = element.tag;

  if (tag === null || tag === undefined) {
    // A "transparent" node: emit its text and children but no tags of its own.
    const text = textOf(element.text);
    if (text) parts.push(escapeCdata(text));
    for (const child of element.children) serializeElement(parts, child);
    const tail = textOf(element.tail);
    if (tail) parts.push(escapeCdata(tail));
    return;
  }

  if (tag === '#comment') {
    parts.push('<!--', escapeCdata(textOf(element.text) || ''), '-->');
    const tail = textOf(element.tail);
    if (tail) parts.push(escapeCdata(tail));
    return;
  }

  if (tag === '#raw') {
    // Pre-serialized markup, inserted verbatim.
    parts.push(textOf(element.text) || '');
    const tail = textOf(element.tail);
    if (tail) parts.push(escapeCdata(tail));
    return;
  }

  parts.push('<', tag);
  for (const [name, value] of element.sortedItems()) {
    if (value !== null && value !== undefined && value !== false) {
      parts.push(' ', name, '="', escapeAttrib(value), '"');
    }
  }

  const text = textOf(element.text);
  const isVoid = HTML_EMPTY.has(tag.toLowerCase());

  if (text || element.children.length > 0 || !isVoid) {
    parts.push('>');
    if (text) {
      if (tag.toLowerCase() === 'script' || tag.toLowerCase() === 'style') {
        parts.push(text);
      } else {
        parts.push(escapeCdata(text));
      }
    }
    for (const child of element.children) serializeElement(parts, child);
    parts.push('</', tag, '>');
  } else {
    parts.push(' />');
  }

  const tail = textOf(element.tail);
  if (tail) parts.push(escapeCdata(tail));
}

/** Serialize a whole tree to an HTML string. */
export function toHtmlString(root) {
  const parts = [];
  serializeElement(parts, root);
  return parts.join('');
}

