/**
 * Storage for chunks of raw HTML pulled out of the document before parsing.
 *
 * Raw block-level HTML must reach the output untouched -- no escaping, no
 * inline processing, no reformatting. Rather than trying to protect it in
 * place, each chunk is swapped for an opaque placeholder that survives the
 * whole pipeline as ordinary text, then substituted back at the very end.
 *
 * This is also why the fourth conversion in the original program is very
 * nearly a no-op: its input is almost entirely block-level HTML, so almost all
 * of it goes straight into the stash and comes back out unchanged.
 */

import { htmlPlaceholder } from './constants.mjs';

export class HtmlStash {
  constructor() {
    this.rawHtml = [];
    this.tagCounter = 0;
    this.tagData = [];
  }

  /**
   * Store a chunk and return the placeholder that stands in for it.
   *
   * `safe` is carried for interface compatibility with the reference
   * implementation; nothing in this configuration consults it.
   */
  store(html, safe = false) {
    const id = this.rawHtml.length;
    this.rawHtml.push(String(html));
    return htmlPlaceholder(id);
  }

  get(id) {
    return this.rawHtml[id];
  }

  reset() {
    this.rawHtml = [];
    this.tagCounter = 0;
    this.tagData = [];
  }

  get size() {
    return this.rawHtml.length;
  }
}

