/**
 * An ordered, named collection of pipeline stages.
 *
 * Every stage of the conversion -- preprocessors, block processors, inline
 * patterns, tree processors, postprocessors -- is held in one of these.
 * Registration takes a priority, and iteration yields highest priority first.
 * Extensions rely on being able to slot themselves between existing stages by
 * choosing a priority, and on being able to replace a stage by name, so both
 * operations are supported directly.
 */

export class Registry {
  constructor() {
    /** Entries as `{ name, item, priority }`, kept sorted on read. */
    this._entries = [];
    this._sorted = null;
  }

  register(item, name, priority) {
    const existing = this._entries.findIndex((entry) => entry.name === name);
    if (existing !== -1) this._entries.splice(existing, 1);
    this._entries.push({ name, item, priority });
    this._sorted = null;
    return this;
  }

  deregister(name, strict = true) {
    const index = this._entries.findIndex((entry) => entry.name === name);
    if (index === -1) {
      if (strict) throw new Error(`No item named "${name}" exists.`);
      return this;
    }
    this._entries.splice(index, 1);
    this._sorted = null;
    return this;
  }

  has(name) {
    return this._entries.some((entry) => entry.name === name);
  }

  get(name) {
    const entry = this._entries.find((item) => item.name === name);
    if (!entry) throw new Error(`No item named "${name}" exists.`);
    return entry.item;
  }

  /** Priority of a registered stage, so a neighbour can be targeted. */
  priorityOf(name) {
    const entry = this._entries.find((item) => item.name === name);
    return entry ? entry.priority : null;
  }

  _ordered() {
    if (this._sorted === null) {
      // Stable descending sort: equal priorities keep registration order.
      this._sorted = this._entries
        .map((entry, index) => ({ entry, index }))
        .sort((left, right) =>
          right.entry.priority - left.entry.priority || left.index - right.index
        )
        .map(({ entry }) => entry.item);
    }
    return this._sorted;
  }

  [Symbol.iterator]() {
    return this._ordered()[Symbol.iterator]();
  }

  toArray() {
    return [...this._ordered()];
  }

  get length() {
    return this._entries.length;
  }
}

