/**
 * Tolerant HTML tokenizer.
 *
 * A port of the scanner the reference implementation borrows from its standard
 * library, reproduced here because the extraction of raw HTML blocks depends on
 * its exact tolerances -- in particular *where* it decides a malformed tag ends,
 * which determines how much text lands in the raw-HTML stash.
 *
 * Written as explicit character scanning. The handler object receives callbacks
 * mirroring the original's method names so the extractor above it reads the
 * same way as the code it mirrors.
 */

import { isAsciiAlpha, isWhitespace } from '../util/chars.mjs';

/** Elements whose content is raw text rather than markup. */
export const CDATA_CONTENT_ELEMENTS = new Set(['script', 'style']);

function isTagNameBodyChar(ch) {
  // `[^\t\n\r\f />]` -- the tolerant tag-name character class.
  return !(ch === '\t' || ch === '\n' || ch === '\r' || ch === '\f' || ch === ' ' || ch === '/' || ch === '>');
}

function isAttrNameBodyChar(ch) {
  // `[^\s/=>]`
  return !(isWhitespace(ch) || ch === '/' || ch === '=' || ch === '>');
}

export class HtmlTokenizer {
  constructor(handler) {
    this.handler = handler;
    this.rawdata = '';
    this.cdataElem = null;
    /** Offset of the current position from the start of its line. */
    this.offset = 0;
    /** Index in `rawdata` where the current line begins. */
    this.lineStart = 0;
  }

  feed(data) {
    this.rawdata += data;
    this._goahead(false);
  }

  close() {
    this._goahead(true);
  }

  setCdataMode(elem) {
    this.cdataElem = elem.toLowerCase();
  }

  clearCdataMode() {
    this.cdataElem = null;
  }

  /** Advance the line/offset bookkeeping from `i` to `j`. */
  _updatePos(i, j) {
    if (i >= j) return j;
    const chunk = this.rawdata.slice(i, j);
    const lastNewline = chunk.lastIndexOf('\n');
    if (lastNewline === -1) {
      this.offset += chunk.length;
    } else {
      this.lineStart = i + lastNewline + 1;
      this.offset = j - this.lineStart;
    }
    return j;
  }

  /** Index in `rawdata` at which the current line starts. */
  get lineOffset() {
    return this.lineStart;
  }

  /** `<` followed by an ASCII letter. */
  _isStartTagOpen(i) {
    return this.rawdata[i] === '<' && isAsciiAlpha(this.rawdata[i + 1]);
  }

  _goahead(end) {
    const rawdata = this.rawdata;
    let i = 0;
    const n = rawdata.length;

    while (i < n) {
      // Text runs until the next `<`; ampersands are ordinary data here, and
      // character references are recognized later during inline processing.
      let j = rawdata.indexOf('<', i);
      if (j === -1) {
        if (this.cdataElem) break;
        j = n;
      }
      if (i < j) this.handler.handleData(rawdata.slice(i, j));
      i = this._updatePos(i, j);
      if (i === n) break;

      let k;
      if (this._isStartTagOpen(i)) {
        k = this._parseStartTag(i);
      } else if (rawdata.startsWith('</', i)) {
        k = this._parseEndTag(i);
      } else if (rawdata.startsWith('<!--', i)) {
        k = this._parseComment(i);
      } else if (rawdata.startsWith('<?', i)) {
        k = this._parsePi(i);
      } else if (rawdata.startsWith('<!', i)) {
        k = this._parseHtmlDeclaration(i);
      } else if (i + 1 < n) {
        this.handler.handleData('<');
        k = i + 1;
      } else {
        break;
      }

      if (k < 0) {
        if (!end) break;
        k = rawdata.indexOf('>', i + 1);
        if (k < 0) {
          k = rawdata.indexOf('<', i + 1);
          if (k < 0) k = i + 1;
        } else {
          k += 1;
        }
        this.handler.handleData(rawdata.slice(i, k));
      }
      i = this._updatePos(i, k);
    }

    if (end && i < n) {
      this.handler.handleData(rawdata.slice(i, n));
      i = this._updatePos(i, n);
    }
    this.rawdata = rawdata.slice(i);
    // Positions restart with the trimmed buffer.
    this.lineStart -= i;
    if (this.lineStart < 0) this.lineStart = 0;
  }

  /** `<!--...-->`, tolerating an unterminated comment. */
  _parseComment(i) {
    const rawdata = this.rawdata;
    const end = rawdata.indexOf('-->', i + 4);
    if (end === -1) return -1;
    this.handler.handleComment(rawdata.slice(i + 4, end));
    return end + 3;
  }

  /** `<?...>` -- the tolerant form terminates at `>`, not `?>`. */
  _parsePi(i) {
    const rawdata = this.rawdata;
    const end = rawdata.indexOf('>', i + 2);
    if (end === -1) return -1;
    this.handler.handlePi(rawdata.slice(i + 2, end));
    return end + 1;
  }

  /** `<!DOCTYPE ...>`, `<![CDATA[...]]>`, or a bogus comment. */
  _parseHtmlDeclaration(i) {
    const rawdata = this.rawdata;
    if (rawdata.startsWith('<!--', i)) return this._parseComment(i);
    if (rawdata.startsWith('<![', i)) return this._parseMarkedSection(i);

    const upper = rawdata.slice(i + 2, i + 9).toUpperCase();
    if (upper === 'DOCTYPE') {
      const end = rawdata.indexOf('>', i + 9);
      if (end === -1) return -1;
      this.handler.handleDecl(rawdata.slice(i + 2, end));
      return end + 1;
    }
    return this._parseBogusComment(i);
  }

  _parseMarkedSection(i) {
    const rawdata = this.rawdata;
    const sectName = rawdata.slice(i + 3, i + 9).toUpperCase();
    if (rawdata.startsWith('<![CDATA[', i)) {
      const end = rawdata.indexOf(']]>', i + 9);
      if (end === -1) return -1;
      this.handler.unknownDecl(rawdata.slice(i + 3, end));
      return end + 3;
    }
    const end = rawdata.indexOf(']>', i + 3);
    if (end === -1) return -1;
    this.handler.unknownDecl(rawdata.slice(i + 3, end));
    return end + 2;
  }

  /** `<!...>` or `</>` -- captured verbatim. */
  _parseBogusComment(i) {
    const rawdata = this.rawdata;
    const end = rawdata.indexOf('>', i + 2);
    if (end === -1) return -1;
    this.handler.handleBogusComment(rawdata.slice(i, end + 1));
    return end + 1;
  }

  /**
   * Locate the end of a start tag, mirroring the tolerant grammar: attribute
   * values may be single-quoted, double-quoted or bare, `/` may appear between
   * attributes, and stray commas are swallowed.
   */
  _locateStartTagEnd(i) {
    const rawdata = this.rawdata;
    const n = rawdata.length;
    let p = i + 1;
    // Tag name.
    while (p < n && isTagNameBodyChar(rawdata[p])) p++;

    for (;;) {
      // Whitespace and slashes before an attribute name.
      const gapStart = p;
      while (p < n && (isWhitespace(rawdata[p]) || rawdata[p] === '/')) p++;
      if (p >= n) return p;

      // An attribute name must be preceded by a quote, whitespace or a slash.
      const prev = rawdata[p - 1];
      const precededOk = p > i + 1 && (prev === '"' || prev === "'" || isWhitespace(prev) || prev === '/');
      if (!precededOk) return gapStart === p ? p : gapStart;
      if (rawdata[p] === '>' || isWhitespace(rawdata[p]) || rawdata[p] === '/') return p;

      // Attribute name: `[^\s/>][^\s/=>]*`
      const nameStart = p;
      p++;
      while (p < n && isAttrNameBodyChar(rawdata[p])) p++;
      if (p === nameStart) return p;

      // Optional value.
      let q = p;
      while (q < n && isWhitespace(rawdata[q])) q++;
      if (q < n && rawdata[q] === '=') {
        while (q < n && rawdata[q] === '=') q++;
        while (q < n && isWhitespace(rawdata[q])) q++;
        if (q < n && (rawdata[q] === '"' || rawdata[q] === "'")) {
          const quote = rawdata[q];
          const close = rawdata.indexOf(quote, q + 1);
          if (close === -1) {
            // Unterminated quote: the tolerant grammar falls back to a bare value.
            while (q < n && !isWhitespace(rawdata[q]) && rawdata[q] !== '>') q++;
          } else {
            q = close + 1;
          }
        } else {
          while (q < n && !isWhitespace(rawdata[q]) && rawdata[q] !== '>') q++;
        }
        p = q;
        // Trailing commas.
        for (;;) {
          let r = p;
          while (r < n && isWhitespace(rawdata[r])) r++;
          if (r < n && rawdata[r] === ',') p = r + 1;
          else break;
        }
      }

      // Whitespace, or a slash not immediately followed by `>`.
      for (;;) {
        if (p < n && isWhitespace(rawdata[p])) p++;
        else if (p < n && rawdata[p] === '/' && rawdata[p + 1] !== '>') p++;
        else break;
      }
      if (p >= n || rawdata[p] === '>' || rawdata[p] === '/') {
        while (p < n && isWhitespace(rawdata[p])) p++;
        return p;
      }
    }
  }

  /** Parse attributes out of the span `[nameEnd, endpos)`. */
  _parseAttrs(start, endpos) {
    const rawdata = this.rawdata;
    const attrs = [];
    let p = start;
    while (p < endpos) {
      while (p < endpos && (isWhitespace(rawdata[p]) || rawdata[p] === '/')) p++;
      if (p >= endpos) break;
      const prev = rawdata[p - 1];
      if (!(prev === '"' || prev === "'" || isWhitespace(prev) || prev === '/')) break;
      if (rawdata[p] === '>') break;

      const nameStart = p;
      p++;
      while (p < endpos && isAttrNameBodyChar(rawdata[p])) p++;
      const name = rawdata.slice(nameStart, p);

      let value = null;
      let q = p;
      while (q < endpos && isWhitespace(rawdata[q])) q++;
      if (q < endpos && rawdata[q] === '=') {
        while (q < endpos && rawdata[q] === '=') q++;
        while (q < endpos && isWhitespace(rawdata[q])) q++;
        if (q < endpos && (rawdata[q] === '"' || rawdata[q] === "'")) {
          const quote = rawdata[q];
          const close = rawdata.indexOf(quote, q + 1);
          if (close !== -1 && close < endpos) {
            value = rawdata.slice(q + 1, close);
            q = close + 1;
          } else {
            const valStart = q;
            while (q < endpos && !isWhitespace(rawdata[q]) && rawdata[q] !== '>') q++;
            value = rawdata.slice(valStart, q);
          }
        } else {
          const valStart = q;
          while (q < endpos && !isWhitespace(rawdata[q]) && rawdata[q] !== '>') q++;
          value = rawdata.slice(valStart, q);
        }
        p = q;
        for (;;) {
          let r = p;
          while (r < endpos && isWhitespace(rawdata[r])) r++;
          if (r < endpos && rawdata[r] === ',') p = r + 1;
          else break;
        }
      }
      attrs.push([name.toLowerCase(), value]);
    }
    return attrs;
  }

  _parseStartTag(i) {
    const rawdata = this.rawdata;
    const endpos = this._locateStartTagEnd(i);
    if (endpos >= rawdata.length) return -1;

    // Tag name.
    let p = i + 1;
    while (p < rawdata.length && isTagNameBodyChar(rawdata[p])) p++;
    const tag = rawdata.slice(i + 1, p).toLowerCase();
    const attrs = this._parseAttrs(p, endpos);

    let end = rawdata.slice(endpos, rawdata.length).slice(0, 2);
    let next;
    if (end.startsWith('>')) {
      next = endpos + 1;
      this.startTagText = rawdata.slice(i, next);
      this.handler.handleStartTag(tag, attrs, this.startTagText);
      if (CDATA_CONTENT_ELEMENTS.has(tag)) this.setCdataMode(tag);
    } else if (end.startsWith('/>')) {
      next = endpos + 2;
      this.startTagText = rawdata.slice(i, next);
      this.handler.handleStartEndTag(tag, attrs, this.startTagText);
    } else {
      // No `>` where one was expected: emit the text as data.
      const lt = rawdata.indexOf('<', i + 1);
      const stop = lt === -1 ? rawdata.length : lt;
      this.handler.handleData(rawdata.slice(i, stop));
      return stop;
    }
    return next;
  }

  /** Match `</name>` allowing surrounding whitespace. */
  _matchEndTagFind(i) {
    const rawdata = this.rawdata;
    let p = i + 2;
    while (p < rawdata.length && isWhitespace(rawdata[p])) p++;
    if (p >= rawdata.length || !isAsciiAlpha(rawdata[p])) return null;
    const nameStart = p;
    while (
      p < rawdata.length &&
