/**
 * Line-level passes that run before block parsing.
 *
 * Three stages, in priority order:
 *
 *  1. `normalize_whitespace` -- canonicalize line endings, expand tabs, and
 *     blank out whitespace-only lines.
 *  2. `html_block` -- lift raw block-level HTML into the stash.
 *  3. `reference` -- collect link reference definitions.
 */

import { expandTabs, strip, replaceAll, rstrip } from '../util/pystr.mjs';
import { STX, ETX, TAB_LENGTH, isBlockLevel } from '../core/constants.mjs';
import { HtmlTokenizer } from './htmlTokenizer.mjs';
import { isWhitespace } from '../util/chars.mjs';

/**
 * Blank out lines that contain nothing but spaces.
 *
 * Only *spaces* count, and only when the line is preceded by a newline, which
 * mirrors the lookbehind in the original and means a whitespace-only first line
 * is left alone.
 */
function blankOutSpaceOnlyLines(source) {
  let out = '';
  let i = 0;
  while (i < source.length) {
    const nl = source.indexOf('\n', i);
    if (nl === -1) {
      out += source.slice(i);
      break;
    }
    const line = source.slice(i, nl);
    const atLineStart = i === 0 || source[i - 1] === '\n';
    let allSpaces = line.length > 0;
    for (let k = 0; k < line.length; k++) {
      if (line[k] !== ' ') { allSpaces = false; break; }
    }
    out += (atLineStart && i !== 0 && allSpaces) ? '\n' : line + '\n';
    i = nl + 1;
  }
  return out;
}

export class NormalizeWhitespace {
  constructor(md) {
    this.md = md;
  }

  run(lines) {
    let source = lines.join('\n');
    source = replaceAll(source, STX, '');
    source = replaceAll(source, ETX, '');
    source = replaceAll(source, '\r\n', '\n');
    source = replaceAll(source, '\r', '\n');
    source += '\n\n';
    source = expandTabs(source, this.md.tabLength);
    source = blankOutSpaceOnlyLines(source);
    return source.split('\n');
  }
}

/**
 * Pull raw block-level HTML out of the document and into the stash.
 *
 * A block-level start tag that begins a line opens a "raw" region; everything
 * up to the matching close tag is captured verbatim, stashed, and replaced by a
 * placeholder standing alone as its own block. Inline-level tags are left in
 * place so the surrounding text still becomes a paragraph.
 *
 * This is what makes the program's fourth conversion nearly idempotent: fed the
 * HTML produced by the first three, almost every line is a block-level element
 * that round-trips through the stash untouched.
 */
class HtmlExtractor {
  constructor(md) {
    this.md = md;
    /** Tags that never have a closing tag and so never open a raw region. */
    this.emptyTags = new Set(['hr']);
    this.reset();
  }

  reset() {
    this.inraw = false;
    this.intail = false;
    this.stack = [];
    this.cache = [];
    this.cleandoc = [];
  }

  /**
   * Is the current position effectively the start of a line?
   *
   * Up to three leading spaces still count -- four would make the content a
   * code block instead.
   */
  atLineStart(tokenizer) {
    if (tokenizer.offset === 0) return true;
    if (tokenizer.offset > 4) return false;
    const start = tokenizer.lineOffset;
    return strip(tokenizer.rawdata.slice(start, start + tokenizer.offset)) === '';
  }

  handleStartTag(tag, attrs, text) {
    if (this.emptyTags.has(tag)) {
      this.handleStartEndTag(tag, attrs, text);
      return;
    }

    if (isBlockLevel(tag) && (this.intail || (this.atLineStart(this._tokenizer) && !this.inraw))) {
      this.inraw = true;
      this.cleandoc.push('\n');
    }

    if (this.inraw) {
      this.stack.push(tag);
      this.cache.push(text);
    } else {
      this.cleandoc.push(text);
      // A lone `<script>`/`<style>` outside a raw region is presumably inside a
      // code span, so raw-text mode would swallow the rest of the document.
      if (tag === 'script' || tag === 'style') this._tokenizer.clearCdataMode();
    }
  }

  handleEndTag(tag, text, afterIndex) {
    if (this.inraw) {
      this.cache.push(text);
      if (this.stack.includes(tag)) {
        while (this.stack.length) {
          if (this.stack.pop() === tag) break;
        }
      }
      if (this.stack.length === 0) {
        const rest = this._tokenizer.rawdata.slice(afterIndex);
        if (this._startsWithBlankLine(rest)) {
          this.cache.push('\n');
        } else {
          this.intail = true;
        }
        this.inraw = false;
        this.cleandoc.push(this.md.htmlStash.store(this.cache.join('')));
        this.cleandoc.push('\n\n');
        this.cache = [];
      }
    } else {
      this.cleandoc.push(text);
    }
  }

  /** `^[ ]*\n` -- spaces then a line break. */
  _startsWithBlankLine(text) {
    let i = 0;
    while (i < text.length && text[i] === ' ') i++;
    return text[i] === '\n';
  }

  handleData(data) {
    if (this.intail && strip(data) !== '') this.intail = false;
    if (this.inraw) this.cache.push(data);
    else this.cleandoc.push(data);
  }

  /** A construct with no separate closing tag. */
  handleEmptyTag(data, isBlock) {
    if (this.inraw || this.intail) {
      this.cache.push(data);
    } else if (this.atLineStart(this._tokenizer) && isBlock) {
      this.cleandoc.push('\n' + this.md.htmlStash.store(data) + '\n\n');
    } else {
      this.cleandoc.push(this.md.htmlStash.store(data));
    }
  }

  handleStartEndTag(tag, attrs, text) {
    this.handleEmptyTag(text, isBlockLevel(tag));
  }

  handleComment(data) {
    this.handleEmptyTag('<!--' + data + '-->', true);
  }

  handleDecl(data) {
    this.handleEmptyTag('<!' + data + '>', true);
  }

  handlePi(data) {
    this.handleEmptyTag('<?' + data + '>', true);
  }

  unknownDecl(data) {
    const end = data.startsWith('CDATA[') ? ']]>' : ']>';
    this.handleEmptyTag('<![' + data + end, true);
  }

  handleBogusComment(data) {
    this.handleEmptyTag(data, false);
  }

  extract(source) {
    this.reset();
    const tokenizer = new HtmlTokenizer(this);
    this._tokenizer = tokenizer;
    tokenizer.parse(source);
    return this.cleandoc.join('');
  }
}

