/**
 * Block-level parsing.
 *
 * The document is split on blank lines into blocks, and each block is offered
 * to the registered processors in priority order. The first one whose `test`
 * passes takes it, and may push leftovers back onto the queue for the others.
 * Processors recurse through the parser, which is how nesting works.
 *
 * The matching that the reference implementation expresses as patterns is done
 * here by explicit scanning, so each processor documents the shape it accepts.
 */

import { Element, subElement, AtomicString, textOf } from '../core/element.mjs';
import { strip, lstrip, rstrip, rstripChars, lstripChars } from '../util/pystr.mjs';
import { isDigit, isWhitespace } from '../util/chars.mjs';

/** HTML-escape the contents of a code block or code span. */
export function codeEscape(text) {
  let out = text;
  if (out.includes('&')) out = out.split('&').join('&amp;');
  if (out.includes('<')) out = out.split('<').join('&lt;');
  if (out.includes('>')) out = out.split('>').join('&gt;');
  return out;
}

/** A stack of parser state names, e.g. `list`, `looselist`, `detabbed`. */
export class State {
  constructor() {
    this.stack = [];
  }

  set(state) {
    this.stack.push(state);
  }

  reset() {
    this.stack.pop();
  }

  isstate(state) {
    return this.stack.length > 0 && this.stack[this.stack.length - 1] === state;
  }
}

export class BlockProcessor {
  constructor(parser) {
    this.parser = parser;
    this.tabLength = parser.md.tabLength;
  }

  lastChild(parent) {
    return parent.children.length ? parent.children[parent.children.length - 1] : null;
  }

  /**
   * Strip one level of indentation from the front of each line.
   *
   * Stops at the first line that is neither indented nor blank, returning the
   * remainder separately so the caller can push it back for reparsing.
   */
  detab(text, length = null) {
    const width = length === null ? this.tabLength : length;
    const pad = ' '.repeat(width);
    const lines = text.split('\n');
    const kept = [];
    for (const line of lines) {
      if (line.startsWith(pad)) kept.push(line.slice(width));
      else if (strip(line) === '') kept.push('');
      else break;
    }
    return [kept.join('\n'), lines.slice(kept.length).join('\n')];
  }

  /** Strip indentation where present, but tolerate dedented lines. */
  looseDetab(text, level = 1) {
    const width = this.tabLength * level;
    const pad = ' '.repeat(width);
    return text
      .split('\n')
      .map((line) => (line.startsWith(pad) ? line.slice(width) : line))
      .join('\n');
  }

  test() {
    return false;
  }

  run() {
    return false;
  }
}

/**
 * Blank blocks.
 *
 * Consumes empties, but when the previous block was a code block the blank
 * lines are appended to it -- blank lines do not terminate an indented code
 * block.
 */
export class EmptyBlockProcessor extends BlockProcessor {
  test(parent, block) {
    return !block || block.startsWith('\n');
  }

  run(parent, blocks) {
    const block = blocks.shift();
    let filler = '\n\n';
    if (block) {
      filler = '\n';
      const theRest = block.slice(1);
      if (theRest) blocks.unshift(theRest);
    }
    const sibling = this.lastChild(parent);
    if (sibling && sibling.tag === 'pre' && sibling.children.length && sibling.children[0].tag === 'code') {
      const code = sibling.children[0];
      code.text = new AtomicString(`${textOf(code.text) ?? ''}${filler}`);
    }
    return undefined;
  }
}

/** Leading-space count, capped so a long run does not matter. */
function leadingSpaces(line) {
  let i = 0;
  while (i < line.length && line[i] === ' ') i++;
  return i;
}

/**
 * Indented content belonging to a list item -- additional paragraphs, nested
 * lists, or code inside an item.
 */
export class ListIndentProcessor extends BlockProcessor {
  constructor(parser) {
    super(parser);
    this.ITEM_TYPES = ['li'];
    this.LIST_TYPES = ['ul', 'ol'];
  }

  test(parent, block) {
    if (!block.startsWith(' '.repeat(this.tabLength))) return false;
    if (this.parser.state.isstate('detabbed')) return false;
    if (this.ITEM_TYPES.includes(parent.tag)) return true;
    const last = this.lastChild(parent);
    return last !== null && this.LIST_TYPES.includes(last.tag);
  }

  run(parent, blocks) {
    let block = blocks.shift();
    const [level, sibling] = this.getLevel(parent, block);
    block = this.looseDetab(block, level);

    this.parser.state.set('detabbed');
    if (this.ITEM_TYPES.includes(parent.tag)) {
      const last = this.lastChild(parent);
      if (last && this.LIST_TYPES.includes(last.tag)) {
        this.parser.parseBlocks(last, [block]);
      } else {
        this.parser.parseBlocks(parent, [block]);
      }
    } else if (this.ITEM_TYPES.includes(sibling.tag)) {
      this.parser.parseBlocks(sibling, [block]);
    } else if (sibling.children.length && this.ITEM_TYPES.includes(sibling.children[sibling.children.length - 1].tag)) {
      const li = sibling.children[sibling.children.length - 1];
      if (textOf(li.text)) {
        // Existing text has to move into a paragraph so the nested block can
        // become a sibling of it rather than being appended to raw text.
        const p = new Element('p');
        p.text = li.text;
        li.text = '';
        li.insert(0, p);
      }
      this.parser.parseChunk(li, block);
    } else {
      this.createItem(sibling, block);
    }
    this.parser.state.reset();
    return undefined;
  }

  createItem(parent, block) {
    const li = subElement(parent, 'li');
    this.parser.parseBlocks(li, [block]);
  }

  /** Walk down the existing list structure to the depth this block indents to. */
  getLevel(parent, block) {
    let indentLevel = 0;
    let i = 0;
    while (block.startsWith(' '.repeat(this.tabLength), i)) {
      indentLevel += 1;
      i += this.tabLength;
    }
    let level = this.parser.state.isstate('list') ? 1 : 0;
    let node = parent;
    while (indentLevel > level) {
      const child = this.lastChild(node);
      if (child !== null && (this.LIST_TYPES.includes(child.tag) || this.ITEM_TYPES.includes(child.tag))) {
        if (this.LIST_TYPES.includes(child.tag)) level += 1;
        node = child;
      } else {
        break;
      }
    }
    return [level, node];
  }
}

/** Four-space-indented code blocks. */
export class CodeBlockProcessor extends BlockProcessor {
  test(parent, block) {
    return block.startsWith(' '.repeat(this.tabLength));
  }

  run(parent, blocks) {
    const sibling = this.lastChild(parent);
    let block = blocks.shift();
    let theRest = '';

    if (sibling && sibling.tag === 'pre' && sibling.children.length && sibling.children[0].tag === 'code') {
      // Continue the previous code block rather than starting a new one.
      const code = sibling.children[0];
      [block, theRest] = this.detab(block);
      code.text = new AtomicString(`${textOf(code.text) ?? ''}\n${codeEscape(rstrip(block))}\n`);
    } else {
      const pre = subElement(parent, 'pre');
      const code = subElement(pre, 'code');
      [block, theRest] = this.detab(block);
      code.text = new AtomicString(`${codeEscape(rstrip(block))}\n`);
    }
    if (theRest) blocks.unshift(theRest);
    return undefined;
  }
}

/**
 * Block quotes.
 *
 * Matches `>` at the start of any line in the block, with up to three leading
 * spaces and one optional space after the marker.
 */
export class BlockQuoteProcessor extends BlockProcessor {
  /** Find the first line in `block` that opens a quote. */
  _search(block) {
    let pos = 0;
    while (pos <= block.length) {
      const lineStart = pos;
      let i = lineStart;
      let spaces = 0;
      while (i < block.length && block[i] === ' ' && spaces < 3) { i++; spaces++; }
      if (block[i] === '>') {
        // The match begins at the newline preceding the line, when there is one.
        return { start: lineStart === 0 ? 0 : lineStart - 1, lineStart };
      }
      const nl = block.indexOf('\n', lineStart);
      if (nl === -1) return null;
      pos = nl + 1;
    }
    return null;
  }

  test(parent, block) {
    return this._search(block) !== null;
  }

  run(parent, blocks) {
    let block = blocks.shift();
    const match = this._search(block);
    if (match) {
      const before = block.slice(0, match.start);
      this.parser.parseBlocks(parent, [before]);
      block = block
        .slice(match.start === 0 ? 0 : match.start + 1)
        .split('\n')
        .map((line) => this.clean(line))
        .join('\n');
    }
    const sibling = this.lastChild(parent);
    const quote = sibling && sibling.tag === 'blockquote' ? sibling : subElement(parent, 'blockquote');

    this.parser.state.set('blockquote');
    this.parser.parseChunk(quote, block);
    this.parser.state.reset();
    return undefined;
  }

  /** Strip a leading `>` and at most one following space. */
  clean(line) {
    if (strip(line) === '>') return '';
    let i = 0;
    let spaces = 0;
    while (i < line.length && line[i] === ' ' && spaces < 3) { i++; spaces++; }
    if (line[i] === '>') {
      i += 1;
      if (line[i] === ' ') i += 1;
      return line.slice(i);
    }
    return line;
  }
}

/**
 * Ordered lists, and -- through the subclass below -- unordered ones.
 *
 * A block is broken into items first, then each item is parsed with the `li`
 * as parent. Whether items are wrapped in paragraphs falls out of the parser
 * state: a tight list sets `list`, which makes the paragraph processor append
 * bare text instead of creating a `p`.
 */
export class OListProcessor extends BlockProcessor {
  constructor(parser) {
    super(parser);
    this.TAG = 'ol';
    this.STARTSWITH = '1';
    this.LAZY_OL = true;
    this.SIBLING_TAGS = ['ol', 'ul'];
  }

  /** `^[ ]{0,3}\d+\.[ ]+(.*)` -- an ordered item at the start of a line. */
  matchItem(line) {
    let i = 0;
    while (i < line.length && line[i] === ' ' && i < this.tabLength - 1) i++;
    if (line[i] === ' ') return null;
    const digitStart = i;
    while (i < line.length && isDigit(line[i])) i++;
    if (i === digitStart) return null;
    const number = line.slice(digitStart, i);
    if (line[i] !== '.') return null;
    i += 1;
    if (line[i] !== ' ') return null;
    while (i < line.length && line[i] === ' ') i++;
    return { marker: number + '.', content: line.slice(i) };
  }

  /** The `RE` test: does the block open with an item of this list's type? */
  test(parent, block) {
    const firstLine = block.split('\n')[0];
    return this.matchItem(firstLine) !== null;
  }

  /**
   * `CHILD_RE` -- an item of *either* list type at up to three spaces of
   * indentation. Secondary lines may switch marker style.
   */
  matchChild(line) {
    let i = 0;
    while (i < line.length && line[i] === ' ' && i < this.tabLength - 1) i++;
    if (line[i] === ' ') return null;
    return this._matchMarkerAt(line, i);
  }

  /**
   * `INDENT_RE` -- an item indented by one to two levels, i.e. a nested item.
   */
  matchIndent(line) {
    let i = 0;
    while (i < line.length && line[i] === ' ') i++;
    if (i < this.tabLength || i > this.tabLength * 2 - 1) return null;
    return this._matchMarkerAt(line, i);
  }

  _matchMarkerAt(line, start) {
    let i = start;
    let marker = null;
    if (line[i] === '*' || line[i] === '+' || line[i] === '-') {
      marker = line[i];
      i += 1;
    } else {
      const digitStart = i;
      while (i < line.length && isDigit(line[i])) i++;
      if (i === digitStart || line[i] !== '.') return null;
      marker = line.slice(digitStart, i + 1);
      i += 1;
    }
    if (line[i] !== ' ') return null;
    while (i < line.length && line[i] === ' ') i++;
    return { marker, content: line.slice(i) };
  }

  run(parent, blocks) {
    const items = this.getItems(blocks.shift());
    const sibling = this.lastChild(parent);
    let lst;

    if (sibling !== null && this.SIBLING_TAGS.includes(sibling.tag)) {
      // Continue the list that ended just above this block.
      lst = sibling;
      const last = lst.children[lst.children.length - 1];
      if (last && textOf(last.text)) {
        const p = new Element('p');
        p.text = last.text;
        last.text = '';
        last.insert(0, p);
      }
      const lch = last ? this.lastChild(last) : null;
      if (lch && textOf(lch.tail)) {
        const p = subElement(last, 'p');
        p.text = lstrip(textOf(lch.tail));
        lch.tail = '';
      }

      const li = subElement(lst, 'li');
      this.parser.state.set('looselist');
      const firstitem = items.shift();
      this.parser.parseBlocks(li, [firstitem]);
      this.parser.state.reset();
    } else if (parent.tag === 'ol' || parent.tag === 'ul') {
      // A multi-item indented list whose first item sat in an empty parent item.
      lst = parent;
    } else {
      lst = subElement(parent, this.TAG);
      if (!this.LAZY_OL && this.STARTSWITH !== '1') lst.set('start', this.STARTSWITH);
    }

    this.parser.state.set('list');
    for (const item of items) {
      if (item.startsWith(' '.repeat(this.tabLength))) {
        this.parser.parseBlocks(lst.children[lst.children.length - 1], [item]);
      } else {
        const li = subElement(lst, 'li');
        this.parser.parseBlocks(li, [item]);
      }
    }
    this.parser.state.reset();
    return undefined;
  }

  /** Split a block into the text of each list item. */
  getItems(block) {
    const items = [];
    for (const line of block.split('\n')) {
      const child = this.matchChild(line);
      if (child) {
        if (items.length === 0 && this.TAG === 'ol') {
          let d = 0;
          while (d < child.marker.length && isDigit(child.marker[d])) d++;
          this.STARTSWITH = child.marker.slice(0, d);
        }
        items.push(child.content);
      } else if (this.matchIndent(line)) {
        if (items.length && items[items.length - 1].startsWith(' '.repeat(this.tabLength))) {
          items[items.length - 1] = `${items[items.length - 1]}\n${line}`;
        } else {
          items.push(line);
        }
      } else if (items.length) {
        items[items.length - 1] = `${items[items.length - 1]}\n${line}`;
      } else {
        items.push(line);
      }
    }
    return items;
  }
}

export class UListProcessor extends OListProcessor {
  constructor(parser) {
    super(parser);
    this.TAG = 'ul';
  }

  matchItem(line) {
    let i = 0;
    while (i < line.length && line[i] === ' ' && i < this.tabLength - 1) i++;
    if (line[i] === ' ') return null;
    if (line[i] !== '*' && line[i] !== '+' && line[i] !== '-') return null;
    const marker = line[i];
    i += 1;
    if (line[i] !== ' ') return null;
    while (i < line.length && line[i] === ' ') i++;
    return { marker, content: line.slice(i) };
  }
}

/**
 * ATX headings.
 *
 * No space is required after the hashes, trailing hashes are dropped, and the
 * heading may appear on any line of the block -- text before and after is
 * pushed back for separate parsing.
 */
export class HashHeaderProcessor extends BlockProcessor {
  /**
   * Find `(?:^|\n)(#{1,6})((?:\\.|[^\\])*?)#*(?:\n|$)`.
   *
   * The hash run is greedy, the heading body is lazy, and a backslash escapes
   * the following character so it cannot end the heading.
   */
  _search(block) {
    for (let start = 0; start <= block.length; start++) {
      if (start !== 0 && block[start - 1] !== '\n') continue;
      if (block[start] !== '#') continue;

      let hashes = 0;
      while (hashes < 6 && block[start + hashes] === '#') hashes++;
      for (let level = hashes; level >= 1; level--) {
        const bodyStart = start + level;
        // Lazy body: grow one unit at a time, a backslash pair counting as one.
        let i = bodyStart;
        for (;;) {
          // Try to close here: greedy trailing hashes, then a line end.
          let j = i;
          while (j < block.length && block[j] === '#') j++;
          for (let k = j; k >= i; k--) {
            if (k === block.length || block[k] === '\n') {
              return {
                start: start === 0 ? 0 : start - 1,
                end: k === block.length ? k : k + 1,
                level,
                body: block.slice(bodyStart, i),
              };
            }
          }
          if (i >= block.length) break;
          if (block[i] === '\n') break;
          i += block[i] === '\\' && i + 1 < block.length ? 2 : 1;
        }
      }
    }
    return null;
  }

  test(parent, block) {
    return this._search(block) !== null;
  }

  run(parent, blocks) {
    const block = blocks.shift();
    const match = this._search(block);
    if (!match) return undefined;
    const before = block.slice(0, match.start);
    const after = block.slice(match.end);
    if (before) this.parser.parseBlocks(parent, [before]);
    const h = subElement(parent, `h${match.level}`);
    h.text = strip(match.body);
    if (after) blocks.unshift(after);
    return undefined;
  }
}

/** Setext headings: a line of text underlined by `=` (h1) or `-` (h2). */
export class SetextHeaderProcessor extends BlockProcessor {
  _match(block) {
    const nl = block.indexOf('\n');
    if (nl === -1) return null;
    const second = block.slice(nl + 1, block.indexOf('\n', nl + 1) === -1 ? block.length : block.indexOf('\n', nl + 1));
    let i = 0;
    while (i < second.length && (second[i] === '=' || second[i] === '-')) i++;
    if (i === 0) return null;
    const underline = second.slice(0, i);
    let j = i;
    while (j < second.length && second[j] === ' ') j++;
    if (j !== second.length) return null;
    return { underline };
  }

  test(parent, block) {
    return this._match(block) !== null;
  }

  run(parent, blocks) {
    const lines = blocks.shift().split('\n');
    const level = lines[1].startsWith('=') ? 1 : 2;
    const h = subElement(parent, `h${level}`);
    h.text = strip(lines[0]);
    if (lines.length > 2) blocks.unshift(lines.slice(2).join('\n'));
    return undefined;
  }
}

/**
 * Horizontal rules.
 *
 * Three or more `-`, `_` or `*`, all the same, optionally separated by one or
 * two spaces, on a line of their own.
 */
export class HRProcessor extends BlockProcessor {
  _isRuleLine(line) {
    let i = 0;
    while (i < line.length && line[i] === ' ' && i < 3) i++;
    const marker = line[i];
    if (marker !== '-' && marker !== '_' && marker !== '*') return false;

    let count = 0;
    while (i < line.length) {
      if (line[i] === marker) {
        count += 1;
        i += 1;
        continue;
      }
      if (line[i] === ' ') {
        let spaces = 0;
        while (i < line.length && line[i] === ' ') { i++; spaces++; }
        if (i === line.length) break; // Trailing spaces are unrestricted.
        if (spaces > 2) return false;
        continue;
      }
      return false;
    }
    return count >= 3;
  }

  _search(block) {
    let pos = 0;
    while (pos <= block.length) {
      const nl = block.indexOf('\n', pos);
      const lineEnd = nl === -1 ? block.length : nl;
      const line = block.slice(pos, lineEnd);
      if (this._isRuleLine(line)) return { start: pos, end: lineEnd };
      if (nl === -1) return null;
      pos = nl + 1;
    }
    return null;
  }

  test(parent, block) {
    this.match = this._search(block);
    return this.match !== null;
  }

  run(parent, blocks) {
    const block = blocks.shift();
    const match = this._search(block);
    if (!match) return undefined;
    const prelines = rstripChars(block.slice(0, match.start), '\n');
    if (prelines) this.parser.parseBlocks(parent, [prelines]);
    subElement(parent, 'hr');
    const postlines = lstripChars(block.slice(match.end), '\n');
    if (postlines) blocks.unshift(postlines);
    return undefined;
  }
}

/**
 * Link reference definitions: `[id]: url "title"`.
 *
 * Runs just above paragraphs and inspects every block, since a definition may
 * be buried among ordinary lines.
 */
export class ReferenceProcessor extends BlockProcessor {
  test() {
    return true;
  }

  /** Locate a definition anywhere in the block, line-anchored. */
  _search(block) {
    let pos = 0;
    while (pos <= block.length) {
      const parsed = this._matchAt(block, pos);
      if (parsed) return parsed;
      const nl = block.indexOf('\n', pos);
      if (nl === -1) return null;
      pos = nl + 1;
    }
    return null;
  }

  _matchAt(block, start) {
    let i = start;
    let spaces = 0;
    while (i < block.length && block[i] === ' ' && spaces < 3) { i++; spaces++; }
    if (block[i] !== '[') return null;
    i += 1;
    const idStart = i;
    while (i < block.length && block[i] !== '[' && block[i] !== ']') i++;
    if (block[i] !== ']') return null;
    const id = block.slice(idStart, i);
    i += 1;
    if (block[i] !== ':') return null;
    i += 1;

    // Spaces, then at most one newline, then more spaces.
    while (block[i] === ' ') i++;
    if (block[i] === '\n') i++;
    while (block[i] === ' ') i++;

    const linkStart = i;
    while (i < block.length && !isWhitespace(block[i])) i++;
    if (i === linkStart) return null;
    const link = block.slice(linkStart, i);
    while (block[i] === ' ') i++;

    // Optional title, possibly on the following line.
    let afterLink = i;
    let j = i;
    if (block[j] === '\n') {
      j += 1;
      while (block[j] === ' ') j++;
    }
    let title = null;
    let end = afterLink;

    const quote = block[j];
    if (quote === '"' || quote === "'" || quote === '(') {
      const closer = quote === '(' ? ')' : quote;
      // The title runs to the last matching delimiter on the line.
      const lineEnd = block.indexOf('\n', j) === -1 ? block.length : block.indexOf('\n', j);
      const close = block.lastIndexOf(closer, lineEnd - 1);
      if (close > j) {
        let k = close + 1;
        while (block[k] === ' ') k++;
        if (k === block.length || block[k] === '\n') {
          title = block.slice(j + 1, close);
          end = k;
        }
      }
    }
    if (title === null) {
      let k = afterLink;
      while (block[k] === ' ') k++;
      if (k !== block.length && block[k] !== '\n') return null;
      end = k;
    }
    return { start, end, id: strip(id).toLowerCase(), link: stripAngles(link), title };
  }

  run(parent, blocks) {
    const block = blocks.shift();
    const match = this._search(block);
    if (match) {
      this.parser.md.references.set(match.id, [match.link, match.title]);
      const after = block.slice(match.end);
      if (strip(after)) blocks.unshift(lstripChars(after, '\n'));
      const before = block.slice(0, match.start);
      if (strip(before)) blocks.unshift(rstripChars(before, '\n'));
      return undefined;
    }
    blocks.unshift(block);
    return false;
  }
}

function stripAngles(link) {
  return rstripChars(lstripChars(link, '<'), '>');
}

/** Everything else becomes a paragraph -- or bare text inside a tight list. */
export class ParagraphProcessor extends BlockProcessor {
  test() {
    return true;
  }

  run(parent, blocks) {
    const block = blocks.shift();
    if (!strip(block)) return undefined;

    if (this.parser.state.isstate('list')) {
      const sibling = this.lastChild(parent);
      if (sibling !== null) {
        const tail = textOf(sibling.tail);
        sibling.tail = tail ? `${tail}\n${block}` : `\n${block}`;
      } else {
        const text = textOf(parent.text);
        parent.text = text ? `${text}\n${block}` : lstrip(block);
      }
    } else {
      const p = subElement(parent, 'p');
      p.text = lstrip(block);
    }
    return undefined;
  }
}

export function buildBlockProcessors(parser, registry) {
  registry.register(new EmptyBlockProcessor(parser), 'empty', 100);
  registry.register(new ListIndentProcessor(parser), 'indent', 90);
  registry.register(new CodeBlockProcessor(parser), 'code', 80);
  registry.register(new HashHeaderProcessor(parser), 'hashheader', 70);
  registry.register(new SetextHeaderProcessor(parser), 'setextheader', 60);
  registry.register(new HRProcessor(parser), 'hr', 50);
  registry.register(new OListProcessor(parser), 'olist', 40);
  registry.register(new UListProcessor(parser), 'ulist', 30);
  registry.register(new BlockQuoteProcessor(parser), 'quote', 20);
  registry.register(new ReferenceProcessor(parser), 'reference', 15);
  registry.register(new ParagraphProcessor(parser), 'paragraph', 10);
  return registry;
}

