/**
 * The block parser: split text into blocks and hand each to the processors.
 */

import { Element } from '../core/element.mjs';
import { Registry } from '../core/registry.mjs';
import { State, buildBlockProcessors } from './processors.mjs';

export class BlockParser {
  constructor(md) {
    this.md = md;
    this.blockprocessors = new Registry();
    this.state = new State();
    this.root = null;
  }

  parseDocument(lines) {
    this.root = new Element(this.md.docTag);
    this.parseChunk(this.root, lines.join('\n'));
    return this.root;
  }

  /** Split on blank lines and parse the resulting blocks under `parent`. */
  parseChunk(parent, text) {
    this.parseBlocks(parent, text.split('\n\n'));
  }

  /**
   * Offer each block to the processors in priority order.
   *
   * `blocks` is consumed destructively: a processor pops the block it handles
   * and may push remainders back, which is how a block containing, say, a
   * heading in the middle gets split.
   */
  parseBlocks(parent, blocks) {
    while (blocks.length) {
      for (const processor of this.blockprocessors) {
        if (processor.test(parent, blocks[0])) {
          if (processor.run(parent, blocks) !== false) break;
        }
      }
    }
  }
}

export function buildBlockParser(md) {
  const parser = new BlockParser(md);
  buildBlockProcessors(parser, parser.blockprocessors);
  return parser;
}

